SELECT i.*,m.canonical_market_key,m.canonical_base_units_per_venue_base_unit,b.* FROM crypto_market_info_perp_soak.order_book_minute AS b FINAL INNER JOIN crypto_market_info_perp_soak.instrument AS i FINAL USING(instrument_id) INNER JOIN (SELECT * FROM crypto_market_info_perp_soak.instrument_canonical_mapping FINAL WHERE mapping_revision='1f287a7cfe9fce6090da2a625f2e770afdf88eb8702c8bce2ecca4c7208f888a') m USING(instrument_id) WHERE m.canonical_base_asset IN ('IOST','NEWT','RVN','ONE','ANIME','BZ','ONG','LSK','DEXE','ICX','BLUR') AND b.minute_time>='2026-09-12 18:30:00' ORDER BY b.minute_time,i.instrument_id
